<?php
declare(strict_types=1);require __DIR__.'/bootstrap.php';$me=sf_admin_require_auth(true);sf_media_ensure_schema();
if(($_SERVER['REQUEST_METHOD']??'')!=='POST')sf_json_response(['ok'=>false,'error'=>'method_not_allowed'],405);
if(empty($_FILES['file'])||!is_array($_FILES['file']))sf_json_response(['ok'=>false,'message'=>'Media file is required.'],422);
try{$asset=sf_media_ingest_upload($_FILES['file'],(int)$me['id']);sf_log_admin_action((int)$me['id'],'media_uploaded','media_asset',(string)$asset['id'],['category'=>$asset['category'],'name'=>$asset['original_name'],'size'=>(int)$asset['size_bytes'],'duration'=>(float)$asset['duration_seconds'],'codec'=>$asset['codec']]);if(function_exists('sf_agent_brain_log'))sf_agent_brain_log((int)$me['id'],'admin_media','media_upload',['route'=>'media_library','action'=>'upload','context_profile'=>'catalog','needs_llm'=>false,'requires_confirmation'=>false,'status'=>'completed','request'=>'Uploaded '.$asset['original_name'],'response'=>'Stored '.$asset['category'].' media asset '.$asset['uuid']]);sf_json_response(['ok'=>true,'asset'=>$asset]);}catch(Throwable $e){sf_json_response(['ok'=>false,'message'=>$e->getMessage()],422);}
